222	// with shuffled arrays and padding, then reads it back through GET /sboms:
223	// all three responses must carry the same record, proving the registration
224	// read path and the paged read path reconstruct manifests identically.
225	func TestReplayAndListReturnIdenticalManifest(t *testing.T) {
226		router, _ := newTestRouter(t)
227	
228		first := `{"artifact":"app","version":"1","components":[
229			{"coordinate":"a","license":"Apache-2.0","dependencies":["b","c"]},
230			{"coordinate":"b","license":"MIT","dependencies":["a"]},
231			{"coordinate":"c","license":"BSD-3-Clause","dependencies":[]}
232		]}`
233		rec := postSBOM(t, router, first)
234		if rec.Code != http.StatusCreated {
235			t.Fatalf("register: %d %s", rec.Code, rec.Body.String())
236		}
237		var created model.SBOM
238		decodeBody(t, rec, &created)
239	
240		replay := `{"artifact":" app ","version":" 1 ","components":[
241			{"coordinate":"c","license":" BSD-3-Clause ","dependencies":[]},
242			{"coordinate":"a","license":"Apache-2.0","dependencies":["c","b"]},
243			{"coordinate":"b","license":"MIT","dependencies":["a"]}
244		]}`
245		rec = postSBOM(t, router, replay)
246		if rec.Code != http.StatusCreated {
247			t.Fatalf("replay: %d %s", rec.Code, rec.Body.String())
248		}
249		var replayed model.SBOM
250		decodeBody(t, rec, &replayed)
251		if replayed.ID != created.ID {
252			t.Fatalf("replay id = %d, want %d", replayed.ID, created.ID)
253		}
254		assertSBOMEqual(t, &replayed, &created)
255	
256		rec = getSBOMs(t, router, "/sboms?artifact=app")
257		if rec.Code != http.StatusOK {
258			t.Fatalf("list: %d %s", rec.Code, rec.Body.String())
259		}
260		var page listResponse
261		decodeBody(t, rec, &page)
262		if page.Total != 1 || len(page.Items) != 1 {
263			t.Fatalf("page = total %d items %d, want 1/1", page.Total, len(page.Items))
264		}
265		if page.Items[0].ID != created.ID {
266			t.Fatalf("listed id = %d, want %d", page.Items[0].ID, created.ID)
267		}
268		assertSBOMEqual(t, page.Items[0], &created)
269	}
