461		// Changed content after reopen still conflicts.
462		expectError(t, postSBOM(t, router2,
463			`{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"X","dependencies":[]}]}`),
464			http.StatusConflict, "SbomConflictError")
