		if rec.Code != http.StatusOK {
			t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
		}
		counters := counted.Snapshot()
		if counters.Selects != 4 {
			t.Fatalf("100-item request issued %d SELECTs, want exactly 4", counters.Selects)
		}
